components.css:
.ds-masthead { min-height: 4rem; display: flex; align-items: center; justify-content: space-between; gap: 1.25rem; padding: .5rem clamp(1.25rem, 3.65vw, 4.5rem); background: var(--color-ink, #11182b); color: var(--color-white, #fff8f8); border-bottom: 1px solid var(--color-border, #38435b); }
.ds-masthead { font-family: var(--font-ui, "Work Sans", system-ui, sans-serif); }
.ds-masthead__title { display: inline-flex; align-items: center; gap: .72rem; font-weight: 650; font-size: .94rem; text-decoration: none; }
.ds-masthead__title { color: inherit; }
.ds-masthead__title svg { color: var(--color-route, #ff806f); flex: none; }
.ds-masthead__nav { display: flex; gap: clamp(1rem, 3vw, 2.25rem); }
.ds-masthead__nav a { display: inline-flex; align-items: center; min-height: 2.75rem; color: var(--color-muted, #b6bfda); font-size: .875rem; font-weight: 550; text-decoration: none; }
.ds-masthead__nav a:hover { color: var(--color-white, #fff8f8); text-decoration: underline; }
.ds-masthead a:focus-visible { outline: 2px solid currentColor; outline-offset: 4px; }

.ds-cover-context { display: inline-flex; padding: .75rem; background: var(--color-ink, #11182b); }
.ds-cover__action { display: inline-flex; align-items: center; justify-content: center; min-height: 2.8rem; margin-top: 1.4rem; padding: .6rem 1.05rem; border-radius: 3px; background: var(--color-route, #ff806f); color: var(--color-ink, #11182b); font-weight: 700; font-size: .88rem; text-decoration: none; }
.ds-cover__action { margin-top: 0; font-family: var(--font-ui, "Work Sans", system-ui, sans-serif); }
.ds-cover__action:hover { background: #ff9c8e; }
.ds-cover__action:focus-visible { outline: 2px solid var(--color-white, #fff8f8); outline-offset: 4px; }

.ds-atlas__legend { color: var(--color-muted, #b6bfda); font-size: .76rem; font-weight: 550; line-height: 1.35; }
.ds-atlas__legend, .ds-atlas__legend span { display: flex; align-items: center; gap: .6rem; }
.ds-atlas__legend { flex-wrap: wrap; gap: .6rem 1.15rem; }
.ds-atlas__legend { margin: 0; padding: .85rem 1.5rem 1.1rem; border-top: 1px solid var(--color-border, #38435b); background: var(--color-ink, #11182b); font-family: var(--font-ui, "Work Sans", system-ui, sans-serif); }
.ds-atlas__legend i { width: 1.25rem; border-top: 2px solid var(--color-route, #ff806f); }
.ds-atlas__legend span:nth-child(2) i { border-top-style: dashed; }
.ds-atlas__legend span:nth-child(3) i { border-top-style: dashed; border-color: var(--color-muted, #b6bfda); }

.ds-atlas__index { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: .35rem; }
.ds-atlas__index { padding: .85rem 1.5rem; background: var(--color-ink, #11182b); font-family: var(--font-ui, "Work Sans", system-ui, sans-serif); }
.ds-atlas__index a { display: grid; min-height: 2.75rem; place-items: center; border: 1px solid var(--color-border, #38435b); border-radius: 3px; color: var(--color-white, #fff8f8); font-size: .83rem; font-weight: 650; font-variant-numeric: tabular-nums; text-decoration: none; }
.ds-atlas__index a:hover { border-color: var(--color-route, #ff806f); }
.ds-atlas__index a[aria-current="location"] { background: var(--color-route, #ff806f); border-color: var(--color-route, #ff806f); color: var(--color-ink, #11182b); }
.ds-atlas__index a:focus-visible { outline: 2px solid var(--color-white, #fff8f8); outline-offset: 4px; }

.ds-pin-example { display: block; background: #151e34; font-family: var(--font-ui, "Work Sans", system-ui, sans-serif); }
.ds-map-pin  { cursor: pointer; outline: none; }
.ds-map-pin__target  { fill: transparent; }
.ds-map-pin__halo  { fill: var(--color-ink, #11182b); stroke: var(--color-route, #ff806f); stroke-width: 1.35; opacity: 0; }
.ds-map-pin__disc  { fill: var(--color-ink, #11182b); stroke: var(--color-route, #ff806f); stroke-width: 2; }
.ds-map-pin__number  { fill: var(--color-white, #fff8f8); font-size: 10.5px; font-weight: 700; pointer-events: none; }
.ds-map-pin__label  { stroke: var(--color-ink, #11182b); stroke-width: 3px; stroke-linejoin: round; paint-order: stroke fill; fill: var(--color-white, #fff8f8); font-size: 13px; font-weight: 650; }
.ds-map-pin:hover .ds-map-pin__label, .ds-map-pin:focus-visible .ds-map-pin__label  { fill: var(--color-route, #ff806f); }
.ds-map-pin.is-current .ds-map-pin__disc, .ds-map-pin:hover .ds-map-pin__disc, .ds-map-pin:focus-visible .ds-map-pin__disc  { fill: var(--color-route, #ff806f); }
.ds-map-pin.is-current .ds-map-pin__number, .ds-map-pin:hover .ds-map-pin__number, .ds-map-pin:focus-visible .ds-map-pin__number  { fill: var(--color-ink, #11182b); }
.ds-map-pin.is-current .ds-map-pin__halo, .ds-map-pin:focus-visible .ds-map-pin__halo  { opacity: 1; }
@media (max-width: 480px) { .ds-map-pin__label { font-size: 15px; } }

.ds-story-chapter { margin-top: clamp(3.5rem, 7vw, 7rem); padding-top: clamp(1.55rem, 3.2vw, 2.5rem); border-top: 1px solid var(--color-rule, #d8d3df); }
.ds-story-chapter { margin: 0; padding-inline: 1.5rem; background: var(--color-paper, #f4f1f5); color: var(--color-ink, #11182b); }
.ds-chapter-head { display: flex; align-items: baseline; gap: clamp(.8rem, 2.1vw, 1.6rem); margin-bottom: 1.5rem; }
.ds-chapter-head h2 { font: 800 clamp(2.6rem, 5vw, 4.4rem)/.95 var(--font-display, "Barlow Condensed", "Arial Narrow", sans-serif); letter-spacing: -.022em; text-wrap: balance; scroll-margin-top: 1.8rem; }
.ds-chapter-head h2 { margin: 0; }
.ds-chapter-index { flex: none; font: 800 clamp(1.55rem, 2.7vw, 2.3rem)/1 var(--font-display, "Barlow Condensed", "Arial Narrow", sans-serif); color: var(--color-route-ink, #a32f25); font-variant-numeric: tabular-nums; }
.ds-chapter-meta { display: flex; align-items: center; flex-wrap: wrap; gap: .55rem; font-size: .8rem; line-height: 1.35; font-weight: 550; font-variant-numeric: tabular-nums; }
.ds-chapter-meta { margin-top: .65rem; color: var(--color-copy, #3f4352); }
.ds-chapter-meta { margin-bottom: 0; font-family: var(--font-ui, "Work Sans", system-ui, sans-serif); }
.ds-chapter-meta span { width: 3px; height: 3px; border-radius: 50%; background: currentColor; }

.ds-ride-facts { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); border-bottom: 1px solid var(--color-rule, #d8d3df); padding-inline: clamp(1.5rem, 5.55vw, 6.5rem); }
.ds-ride-facts { margin: 0; background: var(--color-paper, #f4f1f5); color: var(--color-ink, #11182b); font-family: var(--font-ui, "Work Sans", system-ui, sans-serif); }
.ds-ride-facts div { display: flex; flex-direction: column-reverse; justify-content: center; gap: .24rem; padding-block: 1.12rem 1.05rem; }
.ds-ride-facts div + div { padding-inline-start: clamp(.8rem, 2.3vw, 2rem); border-inline-start: 1px solid var(--color-rule, #d8d3df); }
.ds-ride-facts dd { font: 800 clamp(1.5rem, 3.05vw, 2.4rem)/.96 var(--font-display, "Barlow Condensed", "Arial Narrow", sans-serif); }
.ds-ride-facts dd { margin: 0; }
.ds-ride-facts dt { color: var(--color-copy, #3f4352); font-size: .78rem; line-height: 1.2; font-weight: 560; }

.ds-mobile-route { display: flex; align-items: center; justify-content: center; gap: .55rem; min-height: calc(3rem + env(safe-area-inset-bottom)); padding: .5rem 1rem calc(.5rem + env(safe-area-inset-bottom)); border-top: 1px solid var(--color-border, #38435b); background: var(--color-ink, #11182b); color: var(--color-white, #fff8f8); text-decoration: none; font-size: .875rem; font-weight: 650; font-family: var(--font-ui, "Work Sans", system-ui, sans-serif); }
.ds-mobile-route svg { color: var(--color-route, #ff806f); }
.ds-mobile-route:focus-visible { outline: 2px solid currentColor; outline-offset: 4px; }
